-- Step 5: Photos of a Miniature (Card 7). Ids are uuid v7, generated by the Go code. The image itself lives in
-- Cloudinary (ADR 0005); this table keeps only its name there and what the server checked about it.

-- +goose Up
CREATE TABLE photos (
    id           uuid PRIMARY KEY,
    -- A Miniature's Photos go with it; the service deletes their files from storage (Card 7 rule 6).
    miniature_id uuid        NOT NULL REFERENCES miniatures (id) ON DELETE CASCADE,
    -- The Cloudinary public id, minis/{miniature_id}/{id}, used to build links and to delete the file.
    storage_name text        NOT NULL UNIQUE,
    width        integer     NOT NULL CHECK (width > 0),
    height       integer     NOT NULL CHECK (height > 0),
    -- At most 5 MB (Card 7 rule 2), as measured by Cloudinary after the upload.
    bytes        integer     NOT NULL CHECK (bytes BETWEEN 1 AND 5242880),
    -- The order Photos were added in, 0 to 2 (Card 7 rule 1; no reordering, clarified 2026-10-12).
    position     smallint    NOT NULL CHECK (position BETWEEN 0 AND 2),
    is_cover     boolean     NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    -- DEFERRABLE checks this at the end of each statement instead of row by row, so removing a Photo can move
    -- the ones after it down a place in one UPDATE (positions stay 0, 1, 2 with no gaps).
    UNIQUE (miniature_id, position) DEFERRABLE
);

-- At most one cover per Miniature (Card 7 rule 3). It also serves the Catalog's cover lookup.
CREATE UNIQUE INDEX photos_one_cover_idx ON photos (miniature_id) WHERE is_cover;

-- +goose Down
DROP TABLE photos;
